// #1a311effdd4a2d2ba5fe9c67 — на 1440 сообщение о сбое старта (практика и официальный звонок) в окне, по центру,
// без горизонтальной прокрутки. Кейс CALL-005. НЕ prod-safe: создаёт кандидата «QA-AUTO-CALL-W-…» (link_only);
// официальная попытка НЕ тратится (оба старта — без сети). Кандидат не удаляется (правило проекта).
import { Locator, Page } from '@playwright/test';
import { test, expect } from '../../fixtures';
import { runStamp } from '../support/api';
import {
  TXT, createCandidateLink, launchCandidate, goToPractice, goToOfficialConfirm, tap, expectStartFailure, scrollWidth,
} from './support';

async function expectCenteredNoScroll(page: Page, block: Locator) {
  const box = await block.boundingBox();
  expect(box, 'блок сообщения не найден').not.toBeNull();
  const { sw, vw } = await scrollWidth(page);
  expect(sw, 'горизонтальная прокрутка').toBeLessThanOrEqual(vw);
  expect(box!.x).toBeGreaterThanOrEqual(0);
  expect(box!.x + box!.width).toBeLessThanOrEqual(vw);
  expect(Math.abs(box!.x + box!.width / 2 - vw / 2), 'блок не по центру').toBeLessThanOrEqual(80);
}

test.describe('Звонок кандидата — сообщение о сбое старта на 1440 (#1a311effdd4a2d2ba5fe9c67)', () => {
  test('1440: сообщение о сбое практики и официального — в окне, по центру, без горизонтальной прокрутки @desktop @data #1a311effdd4a2d2ba5fe9c67', async ({ asUser }) => {
    test.setTimeout(5 * 60_000);
    const business = await asUser('business');
    const name = `QA-AUTO-CALL-W-${runStamp()}`;
    const link = await createCandidateLink(business, name);
    test.info().annotations.push({ type: 'test-data', description: `кандидат «${name}» (попытка не использована), не удаляется` });

    const cand = await launchCandidate({ width: 1440, height: 900 });
    try {
      const { page, ctx, counts } = cand;
      await goToPractice(page, link);

      await ctx.setOffline(true);
      await tap(page, 'להתחיל תרגול');
      await expectCenteredNoScroll(page, await expectStartFailure(page, TXT.practiceFail));

      await ctx.setOffline(false);
      await goToOfficialConfirm(page);
      await ctx.setOffline(true);
      await tap(page, 'מוכן, מתחילים');
      await expectCenteredNoScroll(page, await expectStartFailure(page, TXT.officialFail));
      expect(counts.voice, 'звонок не должен был начаться').toBe(0);
    } finally {
      await cand.browser.close();
    }
  });
});
